package com.xiaoxiaoshuo.reader;
import android.app.*;import android.os.*;import android.content.*;import android.graphics.*;import android.graphics.drawable.GradientDrawable;import android.view.*;import android.view.inputmethod.EditorInfo;import android.widget.*;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.*;
public class SearchActivity extends Activity{
 private final int green=Color.rgb(49,88,71);private EditText input;private LinearLayout results,pager;private TextView status,pageInfo;private volatile boolean stopped;private ExecutorService pool;private final Set<String> seen=Collections.synchronizedSet(new LinkedHashSet<>());private final ArrayList<LegacyDexBridge.BookResult> all=new ArrayList<>();private final AtomicInteger done=new AtomicInteger();private String keyword="";private int viewPage=1,sourcePage=1;private final int pageSize=20;private boolean loadingRemote=false,remoteExhausted=false;
 @Override public void onCreate(Bundle b){super.onCreate(b);build();String q=getIntent().getStringExtra("query");if(q!=null&&q.trim().length()>0){input.setText(q);runSearch(q.trim());}else input.requestFocus();}@Override protected void onDestroy(){stopped=true;if(pool!=null)pool.shutdownNow();super.onDestroy();}
 private void build(){LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setBackgroundColor(Color.rgb(247,244,238));root.setPadding(dp(16),dp(12),dp(16),0);LinearLayout top=new LinearLayout(this);top.setGravity(Gravity.CENTER_VERTICAL);TextView back=tx("‹",32,green,true);back.setGravity(Gravity.CENTER);back.setOnClickListener(v->finish());top.addView(back,new LinearLayout.LayoutParams(dp(44),dp(50)));input=new EditText(this);input.setSingleLine(true);input.setHint("搜索书名 / 作者");input.setTextSize(16);input.setPadding(dp(16),0,dp(12),0);input.setImeOptions(EditorInfo.IME_ACTION_SEARCH);GradientDrawable ib=new GradientDrawable();ib.setColor(Color.WHITE);ib.setCornerRadius(dp(16));input.setBackground(ib);top.addView(input,new LinearLayout.LayoutParams(0,dp(50),1));TextView go=tx("搜索",15,green,true);go.setGravity(Gravity.CENTER);go.setOnClickListener(v->runSearch(input.getText().toString().trim()));top.addView(go,new LinearLayout.LayoutParams(dp(68),dp(50)));root.addView(top);status=tx("默认使用智能筛选的80个优质书源",13,Color.rgb(122,116,106),false);status.setPadding(dp(4),dp(12),dp(4),dp(10));root.addView(status);ScrollView sv=new ScrollView(this);results=new LinearLayout(this);results.setOrientation(LinearLayout.VERTICAL);results.setPadding(0,0,0,dp(18));sv.addView(results);root.addView(sv,new LinearLayout.LayoutParams(-1,0,1));pager=new LinearLayout(this);pager.setGravity(Gravity.CENTER);pager.setPadding(0,dp(6),0,dp(10));TextView prev=tx("‹ 上一页",14,green,true);prev.setGravity(Gravity.CENTER);prev.setOnClickListener(v->{if(viewPage>1){viewPage--;renderPage();}});pageInfo=tx("1 / 1",13,Color.rgb(110,105,97),false);pageInfo.setGravity(Gravity.CENTER);TextView next=tx("下一页 ›",14,green,true);next.setGravity(Gravity.CENTER);next.setOnClickListener(v->nextPage());pager.addView(prev,new LinearLayout.LayoutParams(0,dp(44),1));pager.addView(pageInfo,new LinearLayout.LayoutParams(0,dp(44),1));pager.addView(next,new LinearLayout.LayoutParams(0,dp(44),1));root.addView(pager);setContentView(root);getWindow().setStatusBarColor(Color.rgb(247,244,238));getWindow().getDecorView().setSystemUiVisibility(View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR);input.setOnEditorActionListener((v,id,e)->{if(id==EditorInfo.IME_ACTION_SEARCH){runSearch(input.getText().toString().trim());return true;}return false;});}
 private void runSearch(String q){if(q.length()==0){Toast.makeText(this,"请输入书名或作者",Toast.LENGTH_SHORT).show();return;}keyword=q;stopped=false;if(pool!=null)pool.shutdownNow();all.clear();seen.clear();viewPage=1;sourcePage=1;remoteExhausted=false;results.removeAllViews();requestRemotePage();}
 private void requestRemotePage(){if(loadingRemote||remoteExhausted||keyword.length()==0)return;LegacySourceStore.State st=LegacySourceStore.prepare(this,80);ArrayList<LegacySourceStore.SourceInfo> sources=new ArrayList<>(st.selected);if(sources.isEmpty()){status.setText("没有可用外部书源。请到“我的 → 书源管理”添加或恢复书源。");return;}loadingRemote=true;done.set(0);final int requestedPage=sourcePage;final AtomicInteger added=new AtomicInteger();status.setText("正在搜索第 "+requestedPage+" 轮 · "+sources.size()+" 个优质书源…");if(pool!=null)pool.shutdownNow();pool=Executors.newFixedThreadPool(8);for(LegacySourceStore.SourceInfo s:sources){pool.submit(()->{try{if(stopped)return;List<LegacyDexBridge.BookResult> list=LegacyDexBridge.get(this).search(s,keyword,requestedPage);for(LegacyDexBridge.BookResult b:list){if(stopped)break;String key=(b.title+"|"+b.author+"|"+b.bookUrl).toLowerCase(Locale.ROOT);if(seen.add(key)){synchronized(all){all.add(b);}added.incrementAndGet();}}LegacySourceStore.recordHealth(this,s.url,true,1);}catch(Throwable ex){LegacySourceStore.recordHealth(this,s.url,false,6000);}finally{int d=done.incrementAndGet();runOnUiThread(()->{status.setText("第 "+requestedPage+" 轮搜索 · 已完成 "+d+" / "+sources.size()+" · 累计 "+all.size()+" 条");if(d>=sources.size()){loadingRemote=false;if(added.get()==0)remoteExhausted=true;else sourcePage=requestedPage+1;renderPage();}});}});}}
 private void nextPage(){int totalPages=Math.max(1,(all.size()+pageSize-1)/pageSize);if(viewPage<totalPages){viewPage++;renderPage();return;}if(remoteExhausted){Toast.makeText(this,"已经显示全部搜索结果",Toast.LENGTH_SHORT).show();return;}int before=all.size();requestRemotePage();new Handler().postDelayed(()->{int tp=Math.max(1,(all.size()+pageSize-1)/pageSize);if(all.size()>before&&viewPage<tp){viewPage++;renderPage();}},900);}
 private void renderPage(){results.removeAllViews();int total=all.size(),pages=Math.max(1,(total+pageSize-1)/pageSize);if(viewPage>pages)viewPage=pages;int start=(viewPage-1)*pageSize,end=Math.min(total,start+pageSize);ArrayList<LegacyDexBridge.BookResult> copy; synchronized(all){copy=new ArrayList<>(all);}for(int i=start;i<end&&i<copy.size();i++)results.addView(bookCard(copy.get(i)));pageInfo.setText(viewPage+" / "+pages);if(total==0&&!loadingRemote)status.setText("搜索完成 · 暂无结果");else if(!loadingRemote)status.setText("累计找到 "+total+" 条结果 · 每页 "+pageSize+" 条"+(remoteExhausted?" · 已全部加载":" · 翻到末页继续自动加载"));}
 private View bookCard(LegacyDexBridge.BookResult b){LinearLayout card=new LinearLayout(this);card.setOrientation(LinearLayout.HORIZONTAL);card.setPadding(dp(12),dp(12),dp(12),dp(12));GradientDrawable g=new GradientDrawable();g.setColor(Color.WHITE);g.setCornerRadius(dp(18));card.setBackground(g);card.setOnClickListener(v->open(b));ImageView cover=new ImageView(this);cover.setImageDrawable(new LiteraryCoverDrawable(b.title));card.addView(cover,new LinearLayout.LayoutParams(dp(84),dp(118)));CoverLoader.load(cover,b.coverUrl,b.bookUrl.length()>0?b.bookUrl:b.sourceUrl,b.sourceJson,b.title);LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);box.setPadding(dp(14),0,0,0);box.addView(tx(b.title,18,Color.rgb(39,49,44),true));TextView a=tx((b.author.length()>0?b.author:"作者未知")+" · "+(b.sourceName.length()>0?b.sourceName:"外部书源"),12,Color.rgb(128,120,108),false);a.setPadding(0,dp(4),0,dp(7));box.addView(a);TextView intro=tx(b.intro.length()>0?b.intro:"点击查看书籍详情和章节目录",13,Color.rgb(85,82,77),false);intro.setMaxLines(3);box.addView(intro);TextView hint=tx("目录 · 阅读 ›",13,green,true);hint.setGravity(Gravity.RIGHT);box.addView(hint,new LinearLayout.LayoutParams(-1,0,1));card.addView(box,new LinearLayout.LayoutParams(0,dp(118),1));LinearLayout holder=new LinearLayout(this);LinearLayout.LayoutParams cp=new LinearLayout.LayoutParams(-1,-2);cp.bottomMargin=dp(10);holder.addView(card,cp);return holder;}
 private void open(LegacyDexBridge.BookResult b){Intent i=new Intent(this,BookDetailActivity.class);i.putExtra("title",b.title);i.putExtra("author",b.author);i.putExtra("intro",b.intro);i.putExtra("cover",b.coverUrl);i.putExtra("book_url",b.bookUrl);i.putExtra("source_name",b.sourceName);i.putExtra("source_url",b.sourceUrl);i.putExtra("source_json",b.sourceJson);startActivity(i);}private TextView tx(String s,int size,int color,boolean bold){TextView v=new TextView(this);v.setText(s);v.setTextSize(size);v.setTextColor(color);v.setTypeface(Typeface.create("sans",bold?Typeface.BOLD:Typeface.NORMAL));return v;}private int dp(float n){return(int)(n*getResources().getDisplayMetrics().density+.5f);}
}
